import{_ as e,c as r,o as t,a2 as o}from"./chunks/framework.CIiVzG-O.js";const f=JSON.parse('{"title":"よくあるご質問","description":"価格、プライバシー、対応 Mac、フォルダ、言語、購入の復元についての回答です。","frontmatter":{"title":"よくあるご質問","description":"価格、プライバシー、対応 Mac、フォルダ、言語、購入の復元についての回答です。"},"headers":[],"relativePath":"ja/guide/faq.md","filePath":"ja/guide/faq.md","lastUpdated":1794296122000}'),i={name:"ja/guide/faq.md"};function h(l,a,n,d,s,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="よくあるご質問" tabindex="-1">よくあるご質問 <a class="header-anchor" href="#よくあるご質問" aria-label="Permalink to &quot;よくあるご質問&quot;">​</a></h1><h3 id="qdiff-は無料ですか" tabindex="-1">qDiff は無料ですか？ <a class="header-anchor" href="#qdiff-は無料ですか" aria-label="Permalink to &quot;qDiff は無料ですか？&quot;">​</a></h3><p>はい。すべての比較・表示・書き出し機能を、支払いなしでご利用いただけます。 無料版ではタブバーに小さな「未ライセンス」のマークが表示されるだけです。 一度きりの購入でこのマークが消え、今後追加されるプレミアム機能も含まれます。 サブスクリプションも広告もありません。</p><h3 id="購入すると何か機能が増えますか" tabindex="-1">購入すると何か機能が増えますか？ <a class="header-anchor" href="#購入すると何か機能が増えますか" aria-label="Permalink to &quot;購入すると何か機能が増えますか？&quot;">​</a></h3><p>いいえ。すべての機能は最初から利用できます。購入で変わるのは、あのマークが 消えることだけです。今後プレミアム機能を追加する場合も、新しい商品ではなく 同じ一度きりの購入に含まれます。</p><h3 id="購入を復元するには" tabindex="-1">購入を復元するには？ <a class="header-anchor" href="#購入を復元するには" aria-label="Permalink to &quot;購入を復元するには？&quot;">​</a></h3><p><strong>設定 → プレミアム</strong>を開き、<strong>購入を復元</strong>を選びます。購入は Apple ID に 紐づいているため、お使いの他の Mac でも有効です。</p><h3 id="対応している-mac-は" tabindex="-1">対応している Mac は？ <a class="header-anchor" href="#対応している-mac-は" aria-label="Permalink to &quot;対応している Mac は？&quot;">​</a></h3><p>macOS 12 以降で、Apple シリコン搭載 Mac と Intel Mac に対応しています。 <a href="./download.html#system-requirements">システム要件</a>もご覧ください。</p><h3 id="アカウントやインターネット接続は必要ですか" tabindex="-1">アカウントやインターネット接続は必要ですか？ <a class="header-anchor" href="#アカウントやインターネット接続は必要ですか" aria-label="Permalink to &quot;アカウントやインターネット接続は必要ですか？&quot;">​</a></h3><p>いいえ。qDiff はオフラインで動作し、サインインも不要で、バックグラウンド サービスもありません。選んだファイルとフォルダだけを開きます。</p><h3 id="フォルダ全体やアーカイブも比較できますか" tabindex="-1">フォルダ全体やアーカイブも比較できますか？ <a class="header-anchor" href="#フォルダ全体やアーカイブも比較できますか" aria-label="Permalink to &quot;フォルダ全体やアーカイブも比較できますか？&quot;">​</a></h3><p>はい。フォルダは状態フィルタやコピー／同期の操作を備えたツリーで開きます。 .zip や .tar アーカイブも、解凍せずにフォルダのように比較できます。</p><h3 id="画像やテキスト以外のファイルはどうですか" tabindex="-1">画像やテキスト以外のファイルはどうですか？ <a class="header-anchor" href="#画像やテキスト以外のファイルはどうですか" aria-label="Permalink to &quot;画像やテキスト以外のファイルはどうですか？&quot;">​</a></h3><p>画像は並べて表示することも、重ねて表示することもできます。プレーンテキスト ではないファイルも、ごく細かな違いまで比較できます。 <a href="./more.html">その他の比較方法</a>をご覧ください。</p><h3 id="ファイルをアップロードしたり分析したりしますか" tabindex="-1">ファイルをアップロードしたり分析したりしますか？ <a class="header-anchor" href="#ファイルをアップロードしたり分析したりしますか" aria-label="Permalink to &quot;ファイルをアップロードしたり分析したりしますか？&quot;">​</a></h3><p>いいえ。収集・追跡・同期は一切行いません。詳しい説明は <a href="./../privacy/">プライバシーポリシー</a>にあります。</p><h3 id="日本語など他言語のインターフェースはありますか" tabindex="-1">日本語など他言語のインターフェースはありますか？ <a class="header-anchor" href="#日本語など他言語のインターフェースはありますか" aria-label="Permalink to &quot;日本語など他言語のインターフェースはありますか？&quot;">​</a></h3><p>はい。英語、簡体字中国語、繁体字中国語、日本語、ドイツ語、スペイン語、フランス語の 7 言語に対応し、ライトとダークの外観も選べます。</p><h3 id="うまく動きません。どうすればよいですか" tabindex="-1">うまく動きません。どうすればよいですか？ <a class="header-anchor" href="#うまく動きません。どうすればよいですか" aria-label="Permalink to &quot;うまく動きません。どうすればよいですか？&quot;">​</a></h3><p>macOS のバージョンと、起きたことの簡単な説明を添えて <a href="./support.html">お問い合わせ</a>からご連絡ください。スクリーンショットがあると とても助かります。</p>',21)])])}const q=e(i,[["render",h]]);export{f as __pageData,q as default};
